import { onMount } from "solid-js";
import { render } from "solid-js/web";

import { Panel } from "#core/ui-next/components/panel.jsx";
import { Tab } from "#core/ui-next/components/tab.jsx";
import { ActivatableExample } from "#core/ui-next/sandbox/components-browser/activatable-example.jsx";
import { ArrowButtonExample } from "#core/ui-next/sandbox/components-browser/arrow-button-example.jsx";
import { AudioGroupExample } from "#core/ui-next/sandbox/components-browser/audio-group-example.jsx";
import { ButtonExample } from "#core/ui-next/sandbox/components-browser/button-example.jsx";
import { BorderPanel } from "#core/ui-next/sandbox/components-browser/components/border-panel.jsx";
import { TabListLinks } from "#core/ui-next/sandbox/components-browser/components/tab-list-links.jsx";
import { FiligreeExample } from "#core/ui-next/sandbox/components-browser/filigree-example.jsx";
import { FlipbookExample } from "#core/ui-next/sandbox/components-browser/flipbook-example.jsx";
import { HeroButtonExample } from "#core/ui-next/sandbox/components-browser/hero-button-example.jsx";
import { IconExample } from "#core/ui-next/sandbox/components-browser/icon-example.jsx";
import { L10nExample } from "#core/ui-next/sandbox/components-browser/l10n-example.jsx";
import { LinkExample } from "#core/ui-next/sandbox/components-browser/link-example.jsx";
import { NavHelpExample } from "#core/ui-next/sandbox/components-browser/nav-help-example.jsx";
import { PanelExample } from "#core/ui-next/sandbox/components-browser/panel-example.jsx";
import { RadioButtonExample } from "#core/ui-next/sandbox/components-browser/radio-button-example.jsx";
import { ScrollAreaExample } from "#core/ui-next/sandbox/components-browser/scroll-area-example.jsx";
import { SlotExample } from "#core/ui-next/sandbox/components-browser/slot-example.jsx";
import { TabExample } from "#core/ui-next/sandbox/components-browser/tab-example.jsx";
import { TooltipExample } from "#core/ui-next/sandbox/components-browser/tooltip-example.jsx";
import { TriggerExample } from "#core/ui-next/sandbox/components-browser/trigger-example.jsx";
import { VirtualScrollAreaExample } from "#core/ui-next/sandbox/components-browser/virtual-scroll-area-example.jsx";
import { SandboxNavigation } from "#core/ui-next/sandbox/sandbox-navigation.js";

const simpleNav = new SandboxNavigation();

render(() => {
	let ref: HTMLDivElement | undefined;

	onMount(() => {
		simpleNav.setFocus(ref!);
	});

	return (
		<Panel
			id="component-browser-panel"
			name="component-browser"
			class="w-full h-full flex flex-col"
			ref={ref}
		>
			<Tab class="flex flex-row flex-auto m-4">
				<BorderPanel
					class="items-end"
					title="Components"
				>
					<TabListLinks />
				</BorderPanel>
				<BorderPanel
					class="items-center flex-auto"
					title={<Tab.Title />}
				>
					<Tab.Output />
				</BorderPanel>
				<Tab.Item
					name="activatable-example"
					title={() => "Activatable"}
					body={() => <ActivatableExample />}
				/>
				<Tab.Item
					name="arrow-buutton-example"
					title={() => "Arrow Button"}
					body={() => <ArrowButtonExample />}
				/>
				<Tab.Item
					name="audio-group-example"
					title={() => "Audio Group"}
					body={() => <AudioGroupExample />}
				/>
				<Tab.Item
					name="button-example"
					title={() => "Button"}
					body={() => <ButtonExample />}
				/>
				<Tab.Item
					name="filigree-example"
					title={() => "Filigree & Header"}
					body={() => <FiligreeExample />}
				/>
				<Tab.Item
					name="flipbook-example"
					title={() => "Flipbook"}
					body={() => <FlipbookExample />}
				/>
				<Tab.Item
					name="hero-button"
					title={() => "Hero Button"}
					body={() => <HeroButtonExample />}
				/>
				<Tab.Item
					name="icon-example"
					title={() => "Icon"}
					body={() => <IconExample />}
				/>
				<Tab.Item
					name="l10n-example"
					title={() => "L10n"}
					body={() => <L10nExample />}
				/>
				<Tab.Item
					name="link-example"
					title={() => "Link"}
					body={() => <LinkExample />}
				/>
				<Tab.Item
					name="nav-help-example"
					title={() => "Nav Help"}
					body={() => <NavHelpExample />}
				/>
				<Tab.Item
					name="panel-example"
					title={() => "Panel"}
					body={() => <PanelExample />}
				/>
				<Tab.Item
					name="radio-button-example"
					title={() => "Radio Button"}
					body={() => <RadioButtonExample />}
				/>
				<Tab.Item
					name="scroll-area-example"
					title={() => "Scroll Area"}
					body={() => <ScrollAreaExample />}
				/>
				<Tab.Item
					name="slot-example"
					title={() => "Slot"}
					body={() => <SlotExample />}
				/>
				<Tab.Item
					name="tab-example"
					title={() => "Tab"}
					body={() => <TabExample />}
				/>
				<Tab.Item
					name="tooltip-example"
					title={() => "Tooltip"}
					body={() => <TooltipExample />}
				/>
				<Tab.Item
					name="trigger-example"
					title={() => "Trigger"}
					body={() => <TriggerExample />}
				/>
				<Tab.Item
					name="virtual-scroll-area-example"
					title={() => "Virtual Scroll Area"}
					body={() => <VirtualScrollAreaExample />}
				/>
			</Tab>
		</Panel>
	);
}, document.getElementById("root")!);
